from __future__ import annotations

from dataclasses import asdict, dataclass, field
from typing import Any, Literal

ProfileId = Literal["speed", "balanced", "quality"]
ModelKind = Literal["asr", "mt", "vad"]


@dataclass
class ModelSpec:
    id: str
    kind: ModelKind
    name: str
    description: str
    hub_id: str
    local_dirname: str
    size_hint_mb: int = 0
    languages: list[str] = field(default_factory=list)
    quant: str = ""
    backend: str = ""

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


