def get_catalog() -> list[ModelSpec]:
    return list(CATALOG)


def get_spec(model_id: str) -> ModelSpec | None:
    mid = str(model_id or "").strip()
    for spec in CATALOG:
        if spec.id == mid:
            return spec
    return None


# When downloading ASR, also fetch companion weights (aligner, etc.).
# Qwen3-ASR defaults to TEN/VAD frame timing; ForcedAligner is opt-in — do not auto-pull.
MODEL_COMPANIONS: dict[str, tuple[str, ...]] = {}


def expand_model_companions(model_ids: list[str] | None) -> list[str]:
    """Expand download ids with catalog companions (stable order, de-duped)."""
    out: list[str] = []
    seen: set[str] = set()
    for mid in model_ids or []:
        mid_s = str(mid or "").strip()
        if not mid_s or mid_s in seen:
            continue
        seen.add(mid_s)
        out.append(mid_s)
        for dep in MODEL_COMPANIONS.get(mid_s, ()):
            dep_s = str(dep).strip()
            if dep_s and dep_s not in seen:
                seen.add(dep_s)
                out.append(dep_s)
    return out


def resolve_asr_backend(asr_model: str | None) -> str:
    """Map ASR model id → runtime backend key."""
    mid = str(asr_model or "").strip()
    spec = get_spec(mid) if mid else None
    backend = str(getattr(spec, "backend", "") or "").strip().lower() if spec else ""
    if backend in (
        "whisper",
        "sensevoice",
        "reazon-k2",
        "qwen3-asr",
        "qwen3-align",
        "parakeet",
        "cohere-asr",
    ):
        if backend == "qwen3-align":
            return "qwen3-asr"
        return backend
    low = mid.lower()
    if "whisper" in low:
        return "whisper"
    if "reazon" in low:
        return "reazon-k2"
    if "qwen3" in low:
        return "qwen3-asr"
    if "parakeet" in low:
        return "parakeet"
    if "cohere-transcribe" in low or "cohere-asr" in low:
        return "cohere-asr"
    if "sensevoice" in low:
        return "sensevoice"
    return "sensevoice"


def asr_skips_whisper_prompt(asr_model: str | None) -> bool:
    """Models that must not receive Whisper initial_prompt / hotwords.

    anime-whisper (litagin) degrades badly with any initial prompt.
    kotoba CT2 windowed runs also collapse to ~0–1 cues when fed the long
    JA name-bias / mens-esthe hotword lists (measured on ADN-791: 1 vs 1297).
    """
    mid = str(asr_model or "").strip().lower()
    if mid == "anime-whisper" or mid.startswith("anime-whisper"):
        return True
    if mid.startswith("kotoba-whisper"):
        return True
    return False


def asr_is_anime_whisper(asr_model: str | None) -> bool:
    mid = str(asr_model or "").strip().lower()
    return mid == "anime-whisper" or mid.startswith("anime-whisper")


def asr_is_kotoba_whisper(asr_model: str | None) -> bool:
    mid = str(asr_model or "").strip().lower()
    return mid.startswith("kotoba-whisper") or mid.startswith("kotoba-whisper-")


def asr_needs_windowed_transcribe(asr_model: str | None) -> bool:
    """Models that crash or hang on long single-pass faster-whisper runs.

    anime-whisper and kotoba-whisper CT2 builds raise native ACCESS_VIOLATION
    (0xC0000005 / exit 3221225477) on multi-hour media; auto-window those jobs.
    """
    return asr_is_anime_whisper(asr_model) or asr_is_kotoba_whisper(asr_model)


def asr_skips_whisperseg_gating(asr_model: str | None) -> bool:
    """Skip WhisperSeg clip gating for fragile CT2 builds.

    anime: soft-AV islands drop dialogue between moan regions.
    kotoba: clip-gated retranscribe then enables word_timestamps / HST and
    native-crashes (0xC0000005); fixed windows are safer.
    """
    return asr_is_anime_whisper(asr_model) or asr_is_kotoba_whisper(asr_model)


def asr_needs_collapsed_ts_repair(asr_model: str | None) -> bool:
    """Repair collapsed timestamps + optional dual-model align (anime only)."""
    return asr_is_anime_whisper(asr_model)


# Preferred timing models for dual-model align (anime-whisper text + real timestamps).
_TIMING_ALIGN_CANDIDATES = (
    "whisper-ja-1.5b",
    "kotoba-whisper-v2.0-faster",
    "whisper-large-v3-turbo",
    "whisper-large-v2",
    "whisper-large-v3",
    "whisper-tiny",
)


def resolve_timing_align_model(
    asr_model: str | None = None,
    preferred: str | None = None,
) -> str | None:
    """
    Pick an installed Whisper CT2 model that can produce usable timestamps.

    Used for explicit dual-ASR align (``timingAlignModel=whisper-ja-1.5b`` etc.).
    Default anime timing is TEN VAD short frames, not this helper.
    """
    from .download import is_model_installed

    asr = str(asr_model or "").strip()
    asr_l = asr.lower()
    ordered: list[str] = []
    pref = str(preferred or "").strip()
    if pref:
        ordered.append(pref)
    for mid in _TIMING_ALIGN_CANDIDATES:
        if mid not in ordered:
            ordered.append(mid)
    for mid in ordered:
        if mid.lower() == asr_l or mid.lower().startswith("anime-whisper"):
            continue
        try:
            if is_model_installed(mid):
                return mid
        except Exception:
            continue
    return None


def recommend_profile(
    *,
    vram_mb: int = 0,
    ram_mb: int = 0,
    has_cuda: bool = False,
) -> dict[str, Any]:
    if not has_cuda or vram_mb < 4000:
        profile: ProfileId = "speed"
    elif vram_mb < 9000:
        profile = "balanced"
    else:
        profile = "quality"
    models = dict(PROFILES[profile])
    return {
        "profile": profile,
        "models": models,
        "reason": {
            "hasCuda": bool(has_cuda),
            "vramMb": int(vram_mb or 0),
            "ramMb": int(ram_mb or 0),
        },
    }
